<?php /* partial: $f, $classes, $teachers, $subjects, $semesters, $years, $action, $type_select (array|null), $type */ ?>
<form class="row g-2" method="get" action="<?= $action ?>" data-noload>
<?php if (!empty($type_select)): ?><div class="col-md-4"><label class="form-label small mb-0">Jenis</label><select name="type" class="form-select"><?php foreach ($type_select as $k => $l): ?><option value="<?= $k ?>" <?= $k === $type ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<div class="col-6 col-md-2"><label class="form-label small mb-0">Dari</label><input type="date" name="from" value="<?= e($f['from']) ?>" class="form-control" id="pFrom"></div>
<div class="col-6 col-md-2"><label class="form-label small mb-0">Sampai</label><input type="date" name="to" value="<?= e($f['to']) ?>" class="form-control" id="pTo"></div>
<div class="col-md-4"><label class="form-label small mb-0">Periode cepat</label><select class="form-select" id="quick"><option value="">— pilih —</option><option value="day">Hari ini</option><option value="week">Minggu ini</option><option value="month">Bulan ini</option><option value="year">Tahun ini</option></select></div>
<div class="col-md-3"><label class="form-label small mb-0">Tahun Ajaran</label><select name="year_id" class="form-select"><option value="">Semua</option><?php foreach ($years as $y): ?><option value="<?= $y->id ?>" <?= $f['year_id'] == $y->id ? 'selected' : '' ?>><?= e($y->name) ?></option><?php endforeach; ?></select></div>
<div class="col-md-3"><label class="form-label small mb-0">Semester</label><select name="semester_id" class="form-select"><option value="">Semua</option><?php foreach ($semesters as $s): ?><option value="<?= $s->id ?>" <?= $f['semester_id'] == $s->id ? 'selected' : '' ?>><?= e($s->label) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label small mb-0">Kelas</label><select name="class_id" class="form-select"><option value="">Semua</option><?php foreach ($classes as $c): ?><option value="<?= $c->id ?>" <?= $f['class_id'] == $c->id ? 'selected' : '' ?>><?= e($c->name) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label small mb-0">Guru</label><select name="teacher_id" class="form-select"><option value="">Semua</option><?php foreach ($teachers as $c): ?><option value="<?= $c->id ?>" <?= $f['teacher_id'] == $c->id ? 'selected' : '' ?>><?= e($c->name) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label small mb-0">Mapel</label><select name="subject_id" class="form-select"><option value="">Semua</option><?php foreach ($subjects as $c): ?><option value="<?= $c->id ?>" <?= $f['subject_id'] == $c->id ? 'selected' : '' ?>><?= e($c->name) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label small mb-0">Status</label><select name="status" class="form-select"><option value="">Semua</option><?php foreach (array('hadir', 'terlambat', 'sakit', 'izin', 'alpa', 'belum') as $k): ?><option value="<?= $k ?>" <?= $f['status'] === $k ? 'selected' : '' ?>><?= status_label($k) ?></option><?php endforeach; ?></select></div>
<div class="col-12 d-flex gap-2 flex-wrap"><button class="btn btn-primary"><i class="bi bi-funnel"></i> Tampilkan</button><?= isset($extra_buttons) ? $extra_buttons : '' ?></div>
</form>
<script>(function(){var q=document.getElementById('quick');if(!q)return;q.addEventListener('change',function(){var n=new Date(),f=function(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};var a=new Date(n),b=new Date(n);
if(this.value==='week'){var w=(n.getDay()+6)%7;a.setDate(n.getDate()-w);b=new Date(a);b.setDate(a.getDate()+6);}
if(this.value==='month'){a=new Date(n.getFullYear(),n.getMonth(),1);b=new Date(n.getFullYear(),n.getMonth()+1,0);}
if(this.value==='year'){a=new Date(n.getFullYear(),0,1);b=new Date(n.getFullYear(),11,31);}
if(this.value){document.getElementById('pFrom').value=f(a);document.getElementById('pTo').value=f(b);}});})();</script>
